<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import Notice from '../../components/common/Notice.vue'
import LoadingState from '../../components/common/LoadingState.vue'
import ModelRecovery from '../../components/training/ModelRecovery.vue'
import { training, writeTraining, ApiError } from '../../api/training'
import type { Page } from '../../models/training'
interface Feedback { strengths: string[]; gaps: string[]; uncertain: string[]; tradeoffs: string[]; openIssues: string[]; evidenceRefs: { kind: string; quote?: string; checkId?: string; start: number; end: number }[] }
interface Artifact { version: number; fields: Record<string, string>; feedbackStatus: string; feedback?: Feedback; operationId?: string }
interface Stage { id: string; title: string; state: string; currentArtifactVersion: number; draft: Record<string, string>; fieldDefinitions: { id: string; label: string }[]; artifactVersions: Artifact[]; currentArtifact?: Artifact }
interface DesignSession { id: string; revision: number; state: string; currentStage: string; constraints: string; mock: boolean; scenario: { title: string; description: string }; stages: Stage[]; operationId?: string; summary?: { scopeNotice: string; incompleteStages: string[] } }
interface Scenario { id: string; version: string; title: string; description: string }
const route = useRoute(), router = useRouter(), id = computed(() => String(route.params.id || route.query.id || ''))
const session = ref<DesignSession | null>(null), scenarios = ref<Scenario[]>([]), history = ref<DesignSession[]>([]), cursor = ref<string | null>(null), selectedScenario = ref('ORDER_SERVICE'), constraints = ref('')
const stageId = ref(''), draft = ref<Record<string, string>>({}), serverDraft = ref<Record<string, string>>({}), acknowledge = ref(false), invalidate = ref(false), earlyReason = ref('')
const pageRoot = ref<HTMLElement | null>(null), stagePanel = ref<HTMLElement | null>(null), summaryHeading = ref<HTMLElement | null>(null)
const loading = ref(true), busy = ref(false), error = ref(''), message = ref(''), recovery = ref<ApiError | null>(null)
const stage = computed(() => session.value?.stages.find(s => s.id === stageId.value)), editable = computed(() => !loading.value && session.value?.state === 'IN_PROGRESS' && stageId.value === session.value.currentStage && stage.value?.state !== 'FEEDBACK_PENDING')
const feedback = computed(() => stage.value?.currentArtifact?.feedback), hasOpen = computed(() => !!feedback.value && ['gaps', 'uncertain', 'openIssues'].some(k => feedback.value![k as 'gaps'].length > 0))
const stateLabels: Record<string, string> = { EMPTY: '未开始', DRAFT: '草稿', FEEDBACK_PENDING: '反馈生成中', FEEDBACK_READY: '反馈就绪', FEEDBACK_FAILED: '反馈失败', INTERRUPTED: '反馈中断', STALE: '前序已变，需重新评估', IN_PROGRESS: '进行中', COMPLETED: '已完成', ENDED_EARLY: '提前结束' }
const feedbackLabels: Record<string, string> = { strengths: '已有依据的优点', gaps: '仍有缺口', uncertain: '尚待验证', tradeoffs: '方案取舍', openIssues: '未解决事项' }
function fail(e: unknown) { error.value = e instanceof Error ? e.message : '操作失败，输入保留。'; recovery.value = e instanceof ApiError ? e : null }
function selectStage(s: Stage) { stageId.value = s.id; acknowledge.value = false; invalidate.value = false; serverDraft.value = { ...s.draft }; try { draft.value = JSON.parse(sessionStorage.getItem(`v2:design:${id.value}:${s.id}`) || 'null') || { ...s.draft } } catch { draft.value = { ...s.draft } } }
watch(draft, value => { if (id.value && editable.value && !busy.value) try { sessionStorage.setItem(`v2:design:${id.value}:${stageId.value}`, JSON.stringify(value)) } catch { /* 本页文本保留。 */ } }, { deep: true })
async function load(more = false) { loading.value = true; try { if (id.value) { session.value = await training(`/design-sessions/${id.value}`); selectStage(session.value!.stages.find(s => s.id === session.value!.currentStage)!); if (['FEEDBACK_FAILED', 'INTERRUPTED', 'FEEDBACK_PENDING'].includes(stage.value!.state) && session.value!.operationId) recovery.value = Object.assign(new ApiError('反馈尚未完成'), { operationId: session.value!.operationId }) } else { const [ss, p] = await Promise.all([training<Scenario[]>('/design-scenarios'), training<Page<DesignSession>>(`/design-sessions?limit=20&cursor=${encodeURIComponent(more ? cursor.value || '' : '')}`)]); scenarios.value = ss; history.value = more ? [...history.value, ...p.items] : p.items; cursor.value = p.nextCursor } } catch (e) { fail(e) } finally { loading.value = false } }
async function create() { busy.value = true; try { const s = await writeTraining<DesignSession>('/design-sessions', { scenarioId: selectedScenario.value, scenarioVersion: 'v2.1', constraints: constraints.value }); await router.push(`/design-practice/${s.id}`) } catch (e) { fail(e) } finally { busy.value = false } }
async function act(action: string, extra: Record<string, unknown> = {}) {
  if (!session.value || busy.value) return
  const origin = document.activeElement instanceof HTMLElement && pageRoot.value?.contains(document.activeElement) ? document.activeElement : null
  const previousStage = stageId.value
  busy.value = true; error.value = ''; try { session.value = await writeTraining<DesignSession>(`/design-sessions/${id.value}/${action}`, { expectedVersion: session.value.revision, ...extra }, action === 'draft' ? 'PUT' : 'POST'); message.value = action === 'draft' ? '草稿已保存到本机服务。' : '阶段记录已保存；阶段推进由你的明确操作决定。'; if (action === 'submit' || action === 'draft') { sessionStorage.removeItem(`v2:design:${id.value}:${stageId.value}`) } selectStage(session.value.stages.find(s => s.id === session.value!.currentStage)!) } catch (e) { fail(e); try { const latest = await training<DesignSession>(`/design-sessions/${id.value}`); serverDraft.value = latest.stages.find(s => s.id === stageId.value)?.draft || {} } catch { /* 两份文本继续保留。 */ } } finally {
    busy.value = false
    await nextTick()
    // 用户已主动移到其他控件时不抢回焦点；原操作消失时提供明确落点。
    if (origin && (document.activeElement === origin || document.activeElement === document.body)) {
      const firstField = stagePanel.value?.querySelector<HTMLTextAreaElement>('textarea[id^="field-"]')
      if (session.value?.state !== 'IN_PROGRESS') summaryHeading.value?.focus()
      else if (stageId.value !== previousStage || !origin.isConnected || origin.matches(':disabled')) firstField?.focus()
      else origin.focus()
    }
  }
}
onMounted(() => load())
</script>
<template><div ref="pageRoot" class="page training-page"><div class="page-heading"><h1>{{ session ? session.scenario.title : '把设计思路，逐阶段讲清楚。' }}</h1><p>合成场景 · 结构化文本训练。假设、事实与待验证事项分别表达。</p></div><Notice :message="error" kind="error" /><Notice :message="message" /><button v-if="error && id" class="btn btn-secondary" :disabled="busy" @click="load()">保留本页文本并读取最新训练状态</button><ModelRecovery :error="recovery" @recovered="load()" /><LoadingState v-if="loading" label="正在读取设计训练…" />
<template v-if="!id && !loading"><form class="panel training-form" @submit.prevent="create"><h2>开始分阶段训练</h2><div><label for="scenario">合成案例</label><select id="scenario" v-model="selectedScenario"><option v-for="s in scenarios" :key="s.id" :value="s.id">{{ s.title }}</option></select><p class="muted">{{ scenarios.find(s => s.id === selectedScenario)?.description }}</p></div><div><label for="design-constraints">补充约束与假设（可选）</label><textarea id="design-constraints" v-model="constraints" maxlength="6000" rows="4" placeholder="例如先服务单个区域；尚无容量数据，计划通过压测估算。" /></div><button class="btn btn-primary" :disabled="busy">开始五阶段训练</button></form><section class="panel training-section"><h2>已保存的训练</h2><p v-if="!history.length" class="muted">尚无训练记录。提交后，阶段产物和反馈会保存在本机。</p><div v-for="s in history" :key="s.id" class="training-list-row"><div><h3>{{ s.scenario?.title || ((s as any).scenarioId === 'KNOWLEDGE_AGENT' ? '知识库 Agent 设计' : '订单服务设计') }}</h3><p>{{ stateLabels[s.state] }}</p></div><RouterLink class="btn btn-secondary" :to="`/design-practice/${s.id}`">打开训练</RouterLink></div><button v-if="cursor" class="text-link" @click="load(true)">加载更多训练</button></section></template>
<template v-if="session"><div class="training-toolbar"><span class="badge badge-gray">{{ stateLabels[session.state] }}</span><span v-if="session.mock" class="badge badge-orange">Mock · 仅验证流程</span><RouterLink to="/design-practice" class="text-link">训练列表</RouterLink></div><p class="training-intro">{{ session.scenario.description }}</p><ol class="training-stages"><li v-for="(s, i) in session.stages" :key="s.id"><button :aria-current="stageId === s.id ? 'step' : undefined" :disabled="busy || i > session.stages.findIndex(x => x.id === session!.currentStage) && session.state === 'IN_PROGRESS' && !s.currentArtifactVersion" @click="selectStage(s)"><span>{{ i + 1 }}. {{ s.title }}</span><small>{{ stateLabels[s.state] }}</small></button></li></ol>
<div v-if="stage" class="training-reading-layout"><section ref="stagePanel" class="panel training-flow"><h2>{{ stage.title }}</h2><p v-if="stage.state === 'STALE'" class="notice">前序已变化。旧产物仍保留，继续时需作为新版本重新评估。</p><div v-for="f in stage.fieldDefinitions" :key="f.id"><label :for="`field-${f.id}`">{{ f.label }}</label><textarea :id="`field-${f.id}`" v-model="draft[f.id]" :readonly="!editable || busy" maxlength="6000" rows="4" /></div><p class="tiny muted">本阶段合计最多 6000 字符。未知数值写出验证办法；草稿只在明确保存后进入服务端。</p><details v-if="JSON.stringify(draft) !== JSON.stringify(serverDraft)"><summary>查看服务端草稿（本页输入保留）</summary><div v-for="f in stage.fieldDefinitions" :key="f.id"><strong>{{ f.label }}</strong><pre>{{ serverDraft[f.id] || '尚未填写' }}</pre></div></details><div v-if="editable" class="training-action-row"><button class="btn btn-secondary" :disabled="busy" @click="act('draft', { stageId, artifact: draft })">保存阶段草稿</button><button class="btn btn-primary" :disabled="busy || stage.fieldDefinitions.some(f => !draft[f.id]?.trim())" @click="act('submit', { stageId, artifact: draft })">提交产物并调用模型反馈</button><button v-if="stage.currentArtifactVersion" class="text-link" :disabled="busy" @click="act('submit', { stageId, reuseCurrentArtifact: true })">沿用上次产物并重新评估</button></div><details v-if="stage.artifactVersions.length"><summary>本阶段历史提交（{{ stage.artifactVersions.length }}）</summary><article v-for="a in stage.artifactVersions" :key="a.version" class="training-quote"><h3>提交版本 {{ a.version }}</h3><div v-for="f in stage.fieldDefinitions" :key="f.id"><strong>{{ f.label }}</strong><pre>{{ a.fields[f.id] }}</pre></div><p>{{ a.feedbackStatus === 'READY' ? '反馈已保存' : '反馈尚未就绪' }}</p><p v-for="tip in a.feedback?.gaps" :key="tip">{{ tip }}</p></article></details></section>
<aside class="panel training-flow"><h2>本阶段反馈</h2><template v-if="feedback"><section v-for="(label, key) in feedbackLabels" :key="key"><h3>{{ label }}</h3><p v-if="!feedback[key as keyof Omit<Feedback, 'evidenceRefs'>].length" class="muted">本次没有列出条目。</p><p v-for="text in feedback[key as keyof Omit<Feedback, 'evidenceRefs'>]" :key="text">{{ text }}</p></section><details><summary>核对反馈引用</summary><p v-for="(r, i) in feedback.evidenceRefs" :key="i">{{ r.kind === 'QUOTE' ? `产物原文：${r.quote}` : `全文缺失检查：${r.checkId}，范围 ${r.start}–${r.end}` }}</p></details></template><p v-else class="muted">先保存结构化产物，再提交生成反馈。模型不会自动替你进入下一阶段。</p><template v-if="stageId === session.currentStage && session.state === 'IN_PROGRESS' && stage.state === 'FEEDBACK_READY'"><label v-if="hasOpen" class="training-inline-check"><input v-model="acknowledge" type="checkbox" data-confirm-open />我已核对，接受带未解决项继续</label><button class="btn btn-primary" data-action="advance-stage" :disabled="busy || (hasOpen && !acknowledge)" @click="act(stageId === 'TRADEOFFS' ? 'finish' : 'advance', { artifactVersion: stage.currentArtifactVersion, acknowledgeOpenIssues: acknowledge })">{{ stageId === 'TRADEOFFS' ? '结束并保存阶段汇总' : '确认进入下一阶段' }}</button></template><template v-if="session.state === 'IN_PROGRESS' && stage.state !== 'FEEDBACK_PENDING'"><label class="training-inline-check"><input v-model="invalidate" type="checkbox" />我知道重开本阶段会使后续反馈失效，历史保留</label><button class="btn btn-secondary" :disabled="busy || !invalidate" @click="act('reopen', { stageId, acknowledgeInvalidation: invalidate })">重开本阶段</button></template></aside></div>
<section v-if="session.state === 'IN_PROGRESS'" class="panel training-section training-form"><h2>暂时结束训练</h2><label for="early-reason">提前结束原因</label><textarea id="early-reason" v-model="earlyReason" maxlength="1000" rows="2" /><button class="btn btn-secondary" :disabled="busy || !earlyReason.trim()" @click="act('finish', { early: true, reason: earlyReason })">提前结束并保留产物</button></section><section v-if="session.summary" class="panel training-section"><h2 ref="summaryHeading" tabindex="-1">阶段汇总</h2><p>{{ session.summary.scopeNotice }}</p><p v-if="session.summary.incompleteStages.length">未完成：{{ session.summary.incompleteStages.map(s => session!.stages.find(x => x.id === s)?.title).join('、') }}</p><p v-else>五个阶段的有效产物与反馈均已保存，可逐阶段回看。</p></section></template></div></template>
